public.fn_envase_avanca_os.definition:
CREATE OR REPLACE FUNCTION public.fn_envase_avanca_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_os_onfarm_id uuid;
  v_os_id uuid;
BEGIN
  SELECT programacao_id INTO v_prog_id FROM public.lotes WHERE id = NEW.lote_id;
  IF v_prog_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ordem_servico_onfarm_id, ordem_servico_id
    INTO v_os_onfarm_id, v_os_id
    FROM public.programacao_producao
    WHERE id = v_prog_id;

  -- Ensure lote is marked as aprovado (envase only passes if CQ aprovado)
  UPDATE public.lotes SET status = 'aprovado' WHERE id = NEW.lote_id AND status::text <> 'aprovado';
  UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id AND status::text <> 'aprovado';

  IF v_os_onfarm_id IS NOT NULL THEN
    UPDATE public.ordens_servico_onfarm
      SET status = 'pronto_entrega'
      WHERE id = v_os_onfarm_id
        AND status::text = 'envase';
  END IF;

  IF v_os_id IS NOT NULL THEN
    UPDATE public.ordens_servico
      SET status = 'pronto_entrega'
      WHERE id = v_os_id
        AND status::text = 'envase';
  END IF;

  RETURN NEW;
END;
$function$;

public.fn_envase_material_imutavel.definition:
CREATE OR REPLACE FUNCTION public.fn_envase_material_imutavel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Escape controlado apenas para manutenção/fixtures (nunca anon/authenticated).
  IF COALESCE(current_setting('app.estoque_purge_fixture', true), '') = 'on'
     AND current_user NOT IN ('anon','authenticated') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ENVASE_IMUTAVEL: o envase % do lote % nao pode ser excluido. Registre um estorno/novo envase.', OLD.id, OLD.lote_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.lote_id IS DISTINCT FROM OLD.lote_id
     OR NEW.quantidade IS DISTINCT FROM OLD.quantidade
     OR NEW.volume_por_unidade IS DISTINCT FROM OLD.volume_por_unidade THEN
    RAISE EXCEPTION 'ENVASE_IMUTAVEL: lote/quantidade/volume_por_unidade do envase % nao podem ser alterados apos o registro.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$;

public.fn_estoque_ctx_open.definition:
CREATE OR REPLACE FUNCTION public.fn_estoque_ctx_open(p_ctx jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_atual text := NULLIF(current_setting('app.estoque_mov_ctx', true), '');
BEGIN
  -- Contexto externo (operação principal) tem precedência sobre chamadas internas aninhadas
  IF v_atual IS NOT NULL THEN RETURN; END IF;
  PERFORM set_config('app.estoque_mov_ctx', COALESCE(p_ctx, '{}'::jsonb)::text, true);
END; $function$;

public.fn_estoque_ctx_read.definition:
CREATE OR REPLACE FUNCTION public.fn_estoque_ctx_read()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v text;
BEGIN
  v := NULLIF(current_setting('app.estoque_mov_ctx', true), '');
  IF v IS NULL THEN RETURN NULL; END IF;
  RETURN v::jsonb;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END; $function$;

public.fn_estoque_produto_guard.definition:
CREATE OR REPLACE FUNCTION public.fn_estoque_produto_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb := public.fn_estoque_ctx_read();
BEGIN
  IF v_ctx IS NULL OR v_ctx->>'origem' IS NULL THEN
    RAISE EXCEPTION 'estoque_produto so pode ser alterado pelo motor canonico (rpc_estoque_operar_v1)'
      USING ERRCODE = '42501';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;

public.fn_validate_envase_cq.definition:
CREATE OR REPLACE FUNCTION public.fn_validate_envase_cq()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_lote_status TEXT;
    v_cq_resultado TEXT;
BEGIN
    SELECT status INTO v_lote_status FROM public.lotes WHERE id = NEW.lote_id;

    SELECT resultado::text INTO v_cq_resultado
      FROM public.controle_qualidade
     WHERE lote_id = NEW.lote_id
     ORDER BY created_at DESC, seq DESC
     LIMIT 1;

    IF v_lote_status <> 'aprovado' OR v_cq_resultado IS NULL OR v_cq_resultado <> 'aprovado' THEN
        RAISE EXCEPTION 'O lote % não possui Controle de Qualidade aprovado. O envase não é permitido.',
            (SELECT codigo_lote FROM public.lotes WHERE id = NEW.lote_id);
    END IF;

    RETURN NEW;
END;
$function$;

public.fn_validate_envase_volume.definition:
CREATE OR REPLACE FUNCTION public.fn_validate_envase_volume()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_produzido numeric;
  v_envasado numeric;
  v_novo numeric;
  v_codigo text;
  v_saldo numeric;
BEGIN
  IF NEW.quantidade IS NULL OR NEW.quantidade <= 0 THEN
    RAISE EXCEPTION 'A quantidade do envase deve ser maior que zero.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.volume_por_unidade IS NULL OR NEW.volume_por_unidade <= 0 THEN
    RAISE EXCEPTION 'O volume por unidade deve ser maior que zero.' USING ERRCODE = 'check_violation';
  END IF;

  -- H5-B01/B02: serializa qualquer INSERT de envase (inclusive direto via RLS) pela linha do lote.
  -- Ordem de lock compatível com rpc_cockpit_registrar_envase_v1 (programacao -> lote).
  SELECT volume_produzido, codigo_lote INTO v_produzido, v_codigo
  FROM public.lotes WHERE id = NEW.lote_id FOR UPDATE;

  IF v_codigo IS NULL AND v_produzido IS NULL THEN
    RAISE EXCEPTION 'Lote % inexistente para envase.', NEW.lote_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_produzido IS NULL OR v_produzido <= 0 THEN
    RAISE EXCEPTION 'O lote % não possui volume produzido informado. Registre a produção antes de envasar.', COALESCE(v_codigo,'(desconhecido)')
      USING ERRCODE = 'check_violation';
  END IF;

  v_envasado := public.lote_volume_envasado(NEW.lote_id);
  v_novo := COALESCE(NEW.volume_por_unidade,0) * COALESCE(NEW.quantidade,0);
  v_saldo := v_produzido - v_envasado;

  IF (v_envasado + v_novo) > v_produzido THEN
    RAISE EXCEPTION 'Envase excede o volume produzido do lote %. Produzido: % L, já envasado: % L, saldo disponível: % L, solicitado: % L.',
      COALESCE(v_codigo,'(desconhecido)'),
      ROUND(v_produzido/1000.0, 2),
      ROUND(v_envasado/1000.0, 2),
      ROUND(v_saldo/1000.0, 2),
      ROUND(v_novo/1000.0, 2)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$;

public.rpc_cockpit_cancelar_reserva_v1.definition:
CREATE OR REPLACE FUNCTION public.rpc_cockpit_cancelar_reserva_v1(p_item_id uuid, p_os_id uuid, p_origem text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_item public.estoque_produto%ROWTYPE;
  v_main public.estoque_produto%ROWTYPE;
  v_modo text;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  PERFORM public.fn_estoque_ctx_open(jsonb_build_object('acao','cancelamento_reserva','origem','rpc_cockpit_cancelar_reserva_v1','usuario_id',auth.uid()::text));
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_item_id IS NULL OR p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_PARAMS_INVALIDOS'; END IF;
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_MOTIVO_OBRIGATORIO'; END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_reserva:' || p_item_id::text));

  SELECT * INTO v_item FROM public.estoque_produto WHERE id = p_item_id FOR UPDATE;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_NAO_ENCONTRADA'; END IF;

  IF v_item.status::text = 'estornado' OR v_item.quantidade_reservada IS NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true,
      'message', 'Reserva já cancelada anteriormente.');
  END IF;
  IF v_item.status::text = 'expedido' THEN RAISE EXCEPTION 'COCKPIT_RESERVA_JA_EXPEDIDA'; END IF;

  -- coerência: a reserva precisa pertencer à MESMA OS/origem
  IF v_item.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_OS';
  END IF;
  IF coalesce(v_item.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_ORIGEM';
  END IF;

  -- override (cancelar reserva feita por outro operador) exige gestor
  IF v_item.reservado_por IS DISTINCT FROM v_uid AND NOT public.fn_cockpit_is_gestor() THEN
    RAISE EXCEPTION 'COCKPIT_RESERVA_OVERRIDE_SEM_ALCADA';
  END IF;

  -- saldo principal compatível (mesmo lote, envase, item e validade)
  SELECT * INTO v_main
    FROM public.estoque_produto
   WHERE lote_id = v_item.lote_id
     AND envase_id IS NOT DISTINCT FROM v_item.envase_id
     AND produto_id IS NOT DISTINCT FROM v_item.produto_id
     AND microrganismo_id IS NOT DISTINCT FROM v_item.microrganismo_id
     AND validade IS NOT DISTINCT FROM v_item.validade
     AND quantidade_reservada IS NULL
     AND status = 'disponivel'::public.status_estoque
     AND id <> v_item.id
   ORDER BY id LIMIT 1 FOR UPDATE;

  IF v_main.id IS NOT NULL THEN
    v_modo := 'estorno_para_saldo_principal';
    UPDATE public.estoque_produto
       SET quantidade = coalesce(v_main.quantidade,0) + coalesce(v_item.quantidade,0),
           volume_total = coalesce(v_main.volume_total,0) + coalesce(v_item.volume_total,0),
           updated_at = now()
     WHERE id = v_main.id;

    UPDATE public.estoque_produto
       SET status = 'estornado'::public.status_estoque, quantidade = 0, volume_total = 0,
           quantidade_reservada = 0, reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo || format(' — saldo devolvido ao registro %s', v_main.id),
           updated_at = now()
     WHERE id = v_item.id;

  ELSE
    v_modo := 'liberacao_no_proprio_registro';
    UPDATE public.estoque_produto
       SET status = 'disponivel'::public.status_estoque, quantidade_reservada = NULL,
           reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo, updated_at = now()
     WHERE id = v_item.id;

  END IF;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (p_os_id, v_origem, v_item.lote_id, 'estoque_reservado', 'estoque_disponivel',
          'cancelar_reserva_v1', v_uid, format('Cancelamento transacional (%s). Motivo: %s', v_modo, v_motivo));

  RETURN jsonb_build_object('success', true, 'replay', false, 'modo', v_modo,
    'message', 'Reserva cancelada e saldo devolvido em transação única.');
END;
$function$;

public.rpc_cockpit_registrar_envase_v1.definition:
CREATE OR REPLACE FUNCTION public.rpc_cockpit_registrar_envase_v1(p_lote_id uuid, p_os_id uuid, p_origem text, p_programacao_id uuid, p_linhas jsonb, p_validade date, p_operador text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_permitir_parcial boolean DEFAULT false, p_motivo_parcial text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_ctx record;
  v_scope text;
  v_hash text;
  v_row record;
  v_produzido_ml numeric := 0; v_envasado_ml numeric := 0; v_saldo_ml numeric := 0;
  v_total_ml numeric := 0; v_demanda_ml numeric := 0; v_reservado_ml numeric := 0;
  v_pendente_ml numeric := 0;
  v_linha jsonb; v_tipo text; v_qtd integer; v_unit_ml numeric;
  v_reservadas integer; v_livres integer;
  v_envase_id uuid; v_estoque_id uuid;
  v_produto_id uuid; v_micro_id uuid; v_cq_ok boolean; v_lote_status text;
  v_lote_prog uuid;
  v_env_ct int := 0; v_est_ct int := 0; v_res_ml numeric := 0; v_liv_ml numeric := 0;
  v_avanco jsonb; v_result jsonb; v_estado text;
BEGIN
  PERFORM public.fn_estoque_ctx_open(jsonb_build_object('acao','entrada','origem','rpc_cockpit_registrar_envase_v1','usuario_id',auth.uid()::text));
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_lote_id IS NULL OR p_os_id IS NULL OR p_programacao_id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENVASE_PARAMS_INVALIDOS';
  END IF;
  IF p_validade IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENVASE_VALIDADE_OBRIGATORIA'; END IF;
  IF p_validade <= current_date THEN RAISE EXCEPTION 'COCKPIT_ENVASE_VALIDADE_INVALIDA'; END IF;
  IF p_linhas IS NULL OR jsonb_typeof(p_linhas) <> 'array' OR jsonb_array_length(p_linhas) = 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENVASE_SEM_LINHAS';
  END IF;

  -- idempotência: LOCK primeiro, leitura definitiva depois (claim atômico)
  IF nullif(btrim(coalesce(p_idempotency_key, '')), '') IS NOT NULL THEN
    v_scope := 'registrar_envase_v1:' || v_uid::text || ':' || btrim(p_idempotency_key);
    v_hash  := encode(extensions.digest(jsonb_build_object(
                 'lote', p_lote_id, 'os', p_os_id, 'origem', v_origem,
                 'prog', p_programacao_id, 'linhas', p_linhas,
                 'validade', p_validade, 'parcial', p_permitir_parcial)::text, 'sha256'), 'hex');
    PERFORM pg_advisory_xact_lock(hashtext(v_scope));

    SELECT * INTO v_row FROM public.cockpit_operacao_idempotencia
     WHERE idempotency_key = v_scope FOR UPDATE;

    IF v_row.idempotency_key IS NOT NULL THEN
      IF coalesce(v_row.payload_hash, '') <> v_hash THEN
        RAISE EXCEPTION 'COCKPIT_IDEMPOTENCY_CONFLICT';
      END IF;
      IF v_row.resultado IS NOT NULL THEN
        RETURN v_row.resultado || jsonb_build_object('replay', true);
      END IF;
      RAISE EXCEPTION 'COCKPIT_IDEMPOTENCY_IN_PROGRESS';
    END IF;

    INSERT INTO public.cockpit_operacao_idempotencia
      (idempotency_key, operacao, usuario_id, payload_hash, alvo_id, status)
    VALUES (v_scope, 'registrar_envase_v1', v_uid, v_hash, p_lote_id, 'in_progress');
  END IF;

  -- contexto canônico e coerência de vínculos
  SELECT * INTO v_ctx FROM public.fn_cockpit_ctx_programacao(p_programacao_id);
  IF v_ctx.os_id <> p_os_id THEN RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_PROGRAMACAO_OS'; END IF;
  IF v_ctx.origem <> v_origem THEN RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ORIGEM'; END IF;
  IF v_ctx.status_os IN ('cancelada','finalizada') THEN RAISE EXCEPTION 'COCKPIT_OS_ESTADO_TERMINAL'; END IF;
  PERFORM public.fn_cockpit_assert_b2b_liberado(v_ctx.partner_order_id);

  -- lock determinístico: programação e lote
  PERFORM 1 FROM public.programacao_producao WHERE id = p_programacao_id FOR UPDATE;

  SELECT coalesce(volume_produzido, 0), status::text, produto_id, microrganismo_id, programacao_id
    INTO v_produzido_ml, v_lote_status, v_produto_id, v_micro_id, v_lote_prog
    FROM public.lotes WHERE id = p_lote_id FOR UPDATE;

  IF v_lote_status IS NULL THEN RAISE EXCEPTION 'COCKPIT_LOTE_NAO_ENCONTRADO'; END IF;
  IF v_lote_prog IS DISTINCT FROM p_programacao_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_LOTE_PROGRAMACAO';
  END IF;
  IF (v_produto_id IS DISTINCT FROM v_ctx.produto_id)
     AND (v_micro_id IS DISTINCT FROM v_ctx.microrganismo_id) THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ITEM';
  END IF;
  IF v_lote_status = 'reprovado' THEN RAISE EXCEPTION 'COCKPIT_LOTE_REPROVADO_BLOQUEIA_ENVASE'; END IF;
  IF v_produzido_ml <= 0 THEN RAISE EXCEPTION 'COCKPIT_LOTE_SEM_VOLUME_PRODUZIDO'; END IF;

  SELECT (resultado::text = 'aprovado') INTO v_cq_ok
    FROM public.controle_qualidade WHERE lote_id = p_lote_id
   ORDER BY created_at DESC, seq DESC LIMIT 1;
  IF coalesce(v_cq_ok, false) IS NOT TRUE THEN RAISE EXCEPTION 'COCKPIT_ENVASE_EXIGE_CQ_APROVADO'; END IF;

  SELECT coalesce(sum(coalesce(volume_por_unidade,0) * coalesce(quantidade,0)), 0)
    INTO v_envasado_ml FROM public.envase WHERE lote_id = p_lote_id;
  v_saldo_ml := v_produzido_ml - v_envasado_ml;

  v_demanda_ml := coalesce(v_ctx.volume_necessario, 0);
  SELECT coalesce(sum(coalesce(volume_total,0)), 0) * 1000 INTO v_reservado_ml
    FROM public.estoque_produto
   WHERE reservado_para_os_id = p_os_id
     AND coalesce(reservado_para_os_tipo, v_origem) = v_origem
     AND status <> 'estornado'::public.status_estoque;
  v_pendente_ml := greatest(0, v_demanda_ml - v_reservado_ml);

  FOR v_linha IN SELECT * FROM jsonb_array_elements(p_linhas) LOOP
    v_tipo := v_linha->>'tipo_embalagem';
    IF (v_linha->>'quantidade') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'COCKPIT_QUANTIDADE_INVALIDA'; END IF;
    v_qtd := (v_linha->>'quantidade')::int;
    v_unit_ml := CASE v_tipo WHEN 'frasco_1L' THEN 1000 WHEN 'bombona_5L' THEN 5000
                             WHEN 'bombona_20L' THEN 20000 ELSE NULL END;
    IF v_unit_ml IS NULL THEN RAISE EXCEPTION 'COCKPIT_EMBALAGEM_INVALIDA'; END IF;
    IF v_qtd <= 0 THEN RAISE EXCEPTION 'COCKPIT_QUANTIDADE_INVALIDA'; END IF;
    v_total_ml := v_total_ml + (v_unit_ml * v_qtd);
  END LOOP;

  IF v_total_ml > v_saldo_ml THEN RAISE EXCEPTION 'COCKPIT_ENVASE_EXCEDE_PRODUZIDO'; END IF;

  FOR v_linha IN SELECT * FROM jsonb_array_elements(p_linhas) LOOP
    v_tipo := v_linha->>'tipo_embalagem';
    v_qtd  := (v_linha->>'quantidade')::int;
    v_unit_ml := CASE v_tipo WHEN 'frasco_1L' THEN 1000 WHEN 'bombona_5L' THEN 5000
                             WHEN 'bombona_20L' THEN 20000 END;

    INSERT INTO public.envase (lote_id, tipo_embalagem, volume_por_unidade, quantidade, data_envase, operador)
    VALUES (p_lote_id, v_tipo::public.tipo_embalagem, v_unit_ml, v_qtd, current_date, nullif(p_operador, ''))
    RETURNING id INTO v_envase_id;
    v_env_ct := v_env_ct + 1;

    v_reservadas := CASE WHEN v_pendente_ml > 0
                         THEN least(v_qtd, floor(v_pendente_ml / v_unit_ml)::int) ELSE 0 END;
    v_livres := v_qtd - v_reservadas;
    v_pendente_ml := v_pendente_ml - (v_reservadas * v_unit_ml);

    IF v_reservadas > 0 THEN
      INSERT INTO public.estoque_produto (
        produto_id, microrganismo_id, lote_id, envase_id, quantidade, volume_total,
        validade, status, reservado_para_os_id, reservado_para_os_tipo,
        reservado_para_cliente_id, reservado_para_partner_order_id,
        quantidade_reservada, reservado_por, reservado_em
      ) VALUES (
        v_produto_id, v_micro_id, p_lote_id, v_envase_id, v_reservadas,
        (v_unit_ml * v_reservadas) / 1000.0, p_validade, 'reservado'::public.status_estoque,
        p_os_id, v_origem, v_ctx.cliente_id, v_ctx.partner_order_id,
        v_reservadas, v_uid, now()
      ) RETURNING id INTO v_estoque_id;
      v_est_ct := v_est_ct + 1;
      v_res_ml := v_res_ml + (v_unit_ml * v_reservadas);

    END IF;

    IF v_livres > 0 THEN
      INSERT INTO public.estoque_produto (
        produto_id, microrganismo_id, lote_id, envase_id, quantidade, volume_total, validade, status
      ) VALUES (
        v_produto_id, v_micro_id, p_lote_id, v_envase_id, v_livres,
        (v_unit_ml * v_livres) / 1000.0, p_validade, 'disponivel'::public.status_estoque
      ) RETURNING id INTO v_estoque_id;
      v_est_ct := v_est_ct + 1;
      v_liv_ml := v_liv_ml + (v_unit_ml * v_livres);

    END IF;
  END LOOP;

  -- regra canônica de encerramento
  IF v_pendente_ml <= 0 THEN
    v_estado := 'completed';
  ELSIF p_permitir_parcial THEN
    IF NOT public.fn_cockpit_is_gestor() THEN RAISE EXCEPTION 'COCKPIT_ENVASE_PARCIAL_SEM_ALCADA'; END IF;
    IF nullif(btrim(coalesce(p_motivo_parcial, '')), '') IS NULL THEN
      RAISE EXCEPTION 'COCKPIT_ENVASE_PARCIAL_SEM_MOTIVO';
    END IF;
    v_estado := 'completed_override';
  ELSE
    v_estado := 'partial';
  END IF;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, programacao_id, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (p_os_id, v_origem, p_programacao_id, p_lote_id, 'em_envase',
          CASE WHEN v_estado = 'partial' THEN 'em_envase' ELSE 'estoque_gerado' END,
          'registrar_envase_v1', v_uid,
          format('Envase transacional [%s]: %s registros, %s entradas, reservado %s ml, livre %s ml, pendente %s ml. %s',
                 v_estado, v_env_ct, v_est_ct, v_res_ml, v_liv_ml, v_pendente_ml,
                 coalesce('Motivo: ' || nullif(btrim(coalesce(p_motivo_parcial, '')), ''), '')));

  IF v_estado <> 'partial' THEN
    v_avanco := public._rpc_avancar_esteira_laboratorio_internal(p_os_id, v_origem, 'concluir_envase', p_programacao_id);
  ELSE
    v_avanco := jsonb_build_object('success', false, 'motivo', 'COCKPIT_ENVASE_PARCIAL_NAO_AVANCA');
  END IF;

  v_result := jsonb_build_object(
    'success', true, 'replay', false, 'estado', v_estado,
    'envases', v_env_ct, 'entradas_estoque', v_est_ct,
    'volume_reservado_ml', v_res_ml, 'volume_livre_ml', v_liv_ml,
    'pendente_os_ml', v_pendente_ml, 'saldo_restante_ml', v_saldo_ml - v_total_ml,
    'avanco', v_avanco,
    'message', CASE WHEN v_estado = 'partial'
                    THEN 'Envase registrado — necessidade da OS ainda não coberta.'
                    ELSE 'Envase e estoque registrados em transação única.' END);

  IF v_scope IS NOT NULL THEN
    UPDATE public.cockpit_operacao_idempotencia
       SET resultado = v_result, status = 'done', updated_at = now()
     WHERE idempotency_key = v_scope;
  END IF;

  RETURN v_result;
END;
$function$;

public.rpc_criar_embalagens_pos_envase.definition:
CREATE OR REPLACE FUNCTION public.rpc_criar_embalagens_pos_envase(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_qtd int := COALESCE((p_payload->>'quantidade_embalagens')::int, 0);
  v_lote uuid := (p_payload->>'lote_id')::uuid;
  v_volume numeric := (p_payload->>'volume')::numeric;
  v_unidade text := COALESCE(p_payload->>'unidade','L');
  v_gerar_et bool := COALESCE((p_payload->>'gerar_etiqueta_automaticamente')::bool, false);
  v_envase uuid := NULLIF(p_payload->>'envase_id','')::uuid;
  v_produto uuid := NULLIF(p_payload->>'produto_id','')::uuid;
  v_cliente uuid := NULLIF(p_payload->>'cliente_id','')::uuid;
  v_fazenda uuid := NULLIF(p_payload->>'fazenda_id','')::uuid;
  v_fab date; v_val date;
  v_codigo text; v_emb_id uuid; v_etq_id uuid;
  v_arr jsonb := '[]'::jsonb;
  v_meta jsonb;
  v_produto_warning bool := false;
  v_warnings jsonb := '[]'::jsonb;
  i int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(gen_random_uuid()) THEN
    RAISE EXCEPTION 'sem permissão';
  END IF;
  IF v_lote IS NULL THEN RAISE EXCEPTION 'lote_id obrigatório'; END IF;
  IF v_volume IS NULL OR v_volume <= 0 THEN RAISE EXCEPTION 'volume inválido'; END IF;
  IF v_qtd < 1 OR v_qtd > 500 THEN RAISE EXCEPTION 'quantidade entre 1 e 500'; END IF;

  -- Valida referências reais (Fase 2.2)
  IF NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote) THEN
    RAISE EXCEPTION 'Lote informado não existe (%).', v_lote;
  END IF;
  IF v_envase IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.envase WHERE id = v_envase) THEN
    RAISE EXCEPTION 'Envase informado não existe (%).', v_envase;
  END IF;
  IF v_cliente IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = v_cliente) THEN
    RAISE EXCEPTION 'Cliente informado não existe (%).', v_cliente;
  END IF;
  IF v_fazenda IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.fazendas WHERE id = v_fazenda) THEN
    RAISE EXCEPTION 'Fazenda informada não existe (%).', v_fazenda;
  END IF;

  -- Fallback de produto_id a partir do lote
  IF v_produto IS NULL THEN
    SELECT produto_id INTO v_produto FROM public.lotes WHERE id = v_lote;
  END IF;
  IF v_produto IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.produtos WHERE id = v_produto) THEN
    RAISE EXCEPTION 'Produto informado não existe (%).', v_produto;
  END IF;
  IF v_produto IS NULL THEN
    v_produto_warning := true;
    v_warnings := v_warnings || to_jsonb('produto_id_nao_identificado'::text);
  END IF;

  SELECT data_envase INTO v_fab FROM public.envase WHERE id = v_envase;
  IF v_fab IS NULL THEN v_fab := CURRENT_DATE; END IF;
  v_val := v_fab + INTERVAL '6 months';

  FOR i IN 1..v_qtd LOOP
    v_codigo := 'AR-EMB-' || lpad(nextval('public.estoque_embalagem_seq')::text, 6, '0');
    v_meta := jsonb_build_object();
    IF v_produto_warning THEN
      v_meta := v_meta || jsonb_build_object('produto_id_nao_identificado', true);
    END IF;

    INSERT INTO public.estoque_embalagens(
      codigo_embalagem, lote_id, produto_id, envase_id, envase_item_id, volume, unidade, quantidade,
      tipo_embalagem, local_estoque, cliente_id, fazenda_id, fabricado_em, validade_em,
      entrada_estoque_em, criado_por, metadata
    ) VALUES (
      v_codigo, v_lote, v_produto, v_envase,
      NULLIF(p_payload->>'envase_item_id','')::uuid,
      v_volume, v_unidade, 1,
      p_payload->>'tipo_embalagem',
      p_payload->>'local_estoque',
      v_cliente, v_fazenda,
      v_fab, v_val,
      now(), v_uid, v_meta
    ) RETURNING id INTO v_emb_id;

    INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_novo, user_id, metadata)
      VALUES (v_emb_id, 'entrada_estoque', 'em_estoque', v_uid, jsonb_build_object('codigo', v_codigo));

    v_etq_id := NULL;
    IF v_gerar_et THEN
      SELECT (public.rpc_gerar_etiqueta_produto(jsonb_build_object(
        'lote_id', v_lote, 'envase_id', v_envase,
        'produto_id', v_produto,
        'cliente_id', v_cliente,
        'fazenda_id', v_fazenda,
        'volume', v_volume, 'unidade', v_unidade,
        'quantidade_embalagens', 1
      )) ->> 'etiqueta_id')::uuid INTO v_etq_id;

      IF v_etq_id IS NULL THEN
        RAISE EXCEPTION 'Falha ao gerar etiqueta automática para a embalagem. Nenhuma embalagem foi criada. Tente novamente ou gere as embalagens sem etiqueta automática.';
      END IF;

      UPDATE public.estoque_embalagens SET etiqueta_id = v_etq_id WHERE id = v_emb_id;
      UPDATE public.produto_etiquetas SET embalagem_id = v_emb_id WHERE id = v_etq_id;
      INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, user_id, metadata)
        VALUES (v_emb_id, 'etiqueta_vinculada', v_uid, jsonb_build_object('etiqueta_id', v_etq_id));
      INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, metadata)
        VALUES (v_etq_id, 'etiqueta_gerada', v_uid, jsonb_build_object('embalagem_id', v_emb_id));
    END IF;

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
      VALUES ('estoque_embalagem', v_emb_id, 'EMB_CREATED', v_uid,
              jsonb_build_object('codigo', v_codigo, 'etiqueta_id', v_etq_id, 'produto_id', v_produto));

    v_arr := v_arr || jsonb_build_object('embalagem_id', v_emb_id, 'codigo_embalagem', v_codigo, 'etiqueta_id', v_etq_id);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_embalagens', v_qtd,
    'embalagens', v_arr,
    'warnings', v_warnings
  );
END $function$;

public.rpc_estoque_operar_v1.definition:
CREATE OR REPLACE FUNCTION public.rpc_estoque_operar_v1(p_acao text, p_item_id uuid, p_quantidade numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_fp text;
  v_prev public.estoque_movimentacoes%ROWTYPE;
  v_item public.estoque_produto%ROWTYPE;
  v_after public.estoque_produto%ROWTYPE;
  v_mov public.estoque_movimentacoes%ROWTYPE;
  v_ctx jsonb;
  v_qtd numeric := p_quantidade;
  v_motivo text := NULLIF(p_payload->>'motivo','');
  v_origem_mov uuid;
  v_limite numeric;
  v_classif text;
  v_target_id uuid;
  v_lote public.lotes%ROWTYPE;
BEGIN
  PERFORM platform_private.stock_motor_context_set(NULL);
  PERFORM platform_private.stock_motor_actor(p_acao);
  IF (p_quantidade IS NULL AND p_acao IS DISTINCT FROM 'estorno_expedicao') OR
     (p_quantidade IS NOT NULL AND (p_quantidade::text IN ('NaN','Infinity','-Infinity') OR p_quantidade <= 0)) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  IF p_acao = 'ajuste' AND p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida') THEN
    RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO: sentido deve ser entrada ou saida.' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,p_acao,p_payload);
  v_origem_mov := NULLIF(p_payload->>'movimentacao_origem_id','')::uuid;
  IF p_acao IS NULL OR p_acao NOT IN
     ('reserva','cancelamento_reserva','expedicao','entrega','estorno_expedicao','ajuste','perda','descarte','devolucao') THEN
    RAISE EXCEPTION 'ESTQ_ACAO_INVALIDA: ação % não é suportada pelo motor canônico.', p_acao
      USING ERRCODE='check_violation';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'ESTQ_NAO_AUTENTICADO' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.fn_estoque_pode_operar(v_uid, p_acao) THEN
    RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO: perfil não autorizado para %.', p_acao
      USING ERRCODE='insufficient_privilege';
  END IF;
  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_OBRIGATORIA: informe uma chave com ao menos 8 caracteres.'
      USING ERRCODE='check_violation';
  END IF;

  SELECT * INTO v_item FROM public.estoque_produto WHERE id=p_item_id FOR UPDATE;
  PERFORM platform_private.stock_motor_context_set(NULL);
  PERFORM platform_private.stock_motor_actor(p_acao);
  IF (p_quantidade IS NULL AND p_acao IS DISTINCT FROM 'estorno_expedicao') OR
     (p_quantidade IS NOT NULL AND (p_quantidade::text IN ('NaN','Infinity','-Infinity') OR p_quantidade <= 0)) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  IF p_acao = 'ajuste' AND p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida') THEN
    RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO: sentido deve ser entrada ou saida.' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,p_acao,p_payload);
  v_fp := public.fn_estoque_fingerprint(p_acao, p_item_id, p_quantidade, p_payload);
  PERFORM pg_advisory_xact_lock(hashtext('estoque_mov:'||p_idempotency_key));

  SELECT * INTO v_prev FROM public.estoque_movimentacoes
   WHERE idempotency_key = p_idempotency_key LIMIT 1;
  IF FOUND THEN
    IF v_prev.usuario_id IS DISTINCT FROM v_uid OR NOT coalesce(public.stock_p1_movement_owned(v_prev.estoque_produto_id,v_prev.lote_id),false) OR v_prev.metadata->>'stock_request_item' IS DISTINCT FROM p_item_id::text OR v_prev.metadata->>'stock_request_actor' IS DISTINCT FROM v_uid::text THEN
      RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505';
    END IF;
    IF v_prev.request_fingerprint IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO: chave já usada com payload divergente.'
        USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object(
      'ok', true, 'replay', true, 'acao', v_prev.acao,
      'movimentacao_id', v_prev.id, 'estoque_produto_id', v_prev.estoque_produto_id,
      'saldo_anterior', v_prev.saldo_anterior, 'saldo_posterior', v_prev.saldo_posterior,
      'reservado_anterior', v_prev.reservado_anterior, 'reservado_posterior', v_prev.reservado_posterior,
      'status_anterior', v_prev.status_anterior, 'status_novo', v_prev.status_novo);
  END IF;

  SELECT * INTO v_item FROM public.estoque_produto WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ESTQ_ITEM_INEXISTENTE: item % não encontrado.', p_item_id USING ERRCODE='no_data_found';
  END IF;

  IF p_acao <> 'estorno_expedicao' AND (v_qtd IS NULL OR v_qtd <= 0) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser maior que zero.' USING ERRCODE='check_violation';
  END IF;

  v_ctx := jsonb_strip_nulls(jsonb_build_object(
    'reserve_args', jsonb_build_object('os_id',p_payload->>'os_id','os_tipo',COALESCE(p_payload->>'os_tipo','interna'),'cliente_id',NULLIF(p_payload->>'cliente_id',''),'partner_id',NULLIF(p_payload->>'partner_id',''),'partner_order_id',NULLIF(p_payload->>'partner_order_id',''),'observacao',p_payload->>'observacao'),'acao', p_acao, 'origem', COALESCE(p_payload->>'origem','rpc_estoque_operar_v1'),
    'referencia_tipo', p_payload->>'referencia_tipo', 'referencia_id', p_payload->>'referencia_id',
    'motivo', v_motivo, 'idempotency_key', p_idempotency_key, 'request_fingerprint', v_fp,
    'usuario_id', v_uid::text, 'unidade', COALESCE(p_payload->>'unidade','un'),
    'observacao', p_payload->>'observacao',
    'metadata', COALESCE(p_payload->'metadata','{}'::jsonb) || jsonb_build_object('motor','v1','stock_request_item',p_item_id::text,'stock_request_actor',v_uid::text)
  ));

  -- ---------- validações por ação ----------
  IF p_acao = 'reserva' THEN
    IF v_item.status::text <> 'disponivel' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: item não está disponível (%).', v_item.status USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade,0) THEN
      RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: solicitado % > disponível %.', v_qtd, COALESCE(v_item.quantidade,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    v_target_id := public.reservar_estoque_item(
      p_item_id, v_qtd, (p_payload->>'os_id')::uuid, COALESCE(p_payload->>'os_tipo','interna'),
      NULLIF(p_payload->>'cliente_id','')::uuid, NULLIF(p_payload->>'partner_id','')::uuid,
      NULLIF(p_payload->>'partner_order_id','')::uuid, p_payload->>'observacao');

  ELSIF p_acao = 'cancelamento_reserva' THEN
    IF v_item.status::text <> 'reservado' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: item não está reservado.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade_reservada,0) THEN
      RAISE EXCEPTION 'ESTQ_LIBERACAO_EXCEDE: % > reservado %.', v_qtd, COALESCE(v_item.quantidade_reservada,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    IF v_qtd = COALESCE(v_item.quantidade_reservada,0) THEN
      UPDATE public.estoque_produto SET status='disponivel' WHERE id=p_item_id;
    ELSE
      UPDATE public.estoque_produto SET quantidade_reservada = quantidade_reservada - v_qtd WHERE id=p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'expedicao' THEN
    IF v_item.status::text <> 'reservado' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: só é possível expedir item reservado.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade_reservada,0) THEN
      RAISE EXCEPTION 'ESTQ_EXPEDICAO_EXCEDE: % > reservado %.', v_qtd, COALESCE(v_item.quantidade_reservada,0)
        USING ERRCODE='check_violation';
    END IF;
    IF (p_payload->>'cliente_id') IS NOT NULL
       AND v_item.reservado_para_cliente_id IS NOT NULL
       AND v_item.reservado_para_cliente_id <> (p_payload->>'cliente_id')::uuid THEN
      RAISE EXCEPTION 'ESTQ_ESCOPO_INVALIDO: item reservado para outro cliente.' USING ERRCODE='insufficient_privilege';
    END IF;
    IF (p_payload->>'os_id') IS NOT NULL
       AND v_item.reservado_para_os_id IS NOT NULL
       AND v_item.reservado_para_os_id <> (p_payload->>'os_id')::uuid THEN
      RAISE EXCEPTION 'ESTQ_ESCOPO_INVALIDO: item reservado para outra OS/pedido.' USING ERRCODE='insufficient_privilege';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    IF v_qtd = COALESCE(v_item.quantidade_reservada,0) THEN
      UPDATE public.estoque_produto SET status='expedido', expedido_em=now(), expedido_por=v_uid WHERE id=p_item_id;
    ELSE
      -- expedição parcial: baixa somente a quantidade autorizada
      UPDATE public.estoque_produto
         SET quantidade = GREATEST(COALESCE(quantidade,0) - v_qtd, 0),
             quantidade_reservada = COALESCE(quantidade_reservada,0) - v_qtd
       WHERE id = p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'entrega' THEN
    IF v_item.status::text NOT IN ('reservado','expedido') THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: entrega exige item reservado ou expedido.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade,0) THEN
      RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: entrega % > saldo %.', v_qtd, COALESCE(v_item.quantidade,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    UPDATE public.estoque_produto
       SET quantidade = COALESCE(quantidade,0) - v_qtd,
           quantidade_reservada = GREATEST(COALESCE(quantidade_reservada,0) - v_qtd, 0),
           status = 'expedido', expedido_em = COALESCE(expedido_em, now()), expedido_por = COALESCE(expedido_por, v_uid)
     WHERE id = p_item_id;
    v_target_id := p_item_id;

  ELSIF p_acao = 'estorno_expedicao' THEN
    IF v_origem_mov IS NULL THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_SEM_ORIGEM: informe movimentacao_origem_id.' USING ERRCODE='check_violation';
    END IF;
    SELECT * INTO v_mov FROM public.estoque_movimentacoes WHERE id = v_origem_mov;
    IF NOT FOUND OR v_mov.estoque_produto_id <> p_item_id THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_ORIGEM_INVALIDA' USING ERRCODE='check_violation';
    END IF;
    IF v_mov.acao IN ('estorno_expedicao','devolucao') THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_DE_ESTORNO: operação não permitida.' USING ERRCODE='check_violation';
    END IF;
    IF v_mov.acao NOT IN ('expedicao','entrega') THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_ACAO_INVALIDA: só expedição/entrega pode ser estornada.' USING ERRCODE='check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM public.estoque_movimentacoes WHERE movimentacao_origem_id = v_origem_mov) THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_DUPLICADO: movimentação já estornada.' USING ERRCODE='23505';
    END IF;
    v_qtd := COALESCE(v_qtd, v_mov.quantidade);
    v_ctx := v_ctx || jsonb_build_object('movimentacao_origem_id', v_origem_mov::text);
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    UPDATE public.estoque_produto
       SET quantidade = COALESCE(quantidade,0) + COALESCE(v_mov.saldo_anterior,0) - COALESCE(v_mov.saldo_posterior,0),
           quantidade_reservada = COALESCE(v_mov.reservado_anterior, quantidade_reservada),
           status = COALESCE(v_mov.status_anterior, status::text)::status_estoque,
           expedido_em = NULL, expedido_por = NULL
     WHERE id = p_item_id;
    v_target_id := p_item_id;

  ELSIF p_acao IN ('ajuste','perda','descarte') THEN
    IF v_motivo IS NULL THEN
      RAISE EXCEPTION 'ESTQ_MOTIVO_OBRIGATORIO: informe o motivo para %.', p_acao USING ERRCODE='check_violation';
    END IF;
    SELECT limite_ajuste_sem_aprovacao INTO v_limite FROM public.estoque_politicas LIMIT 1;
    IF p_acao <> 'ajuste' OR COALESCE(p_payload->>'sentido','saida') = 'saida' THEN
      IF v_qtd > COALESCE(v_limite,10)
         AND NOT (public.has_role(v_uid,'administrador'::app_role) OR public.has_role(v_uid,'gestor'::app_role)) THEN
        RAISE EXCEPTION 'ESTQ_APROVACAO_REQUERIDA: redução de % excede o limite % sem aprovação.', v_qtd, v_limite
          USING ERRCODE='insufficient_privilege';
      END IF;
      IF v_qtd > COALESCE(v_item.quantidade,0) THEN
        RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: redução % > saldo %.', v_qtd, COALESCE(v_item.quantidade,0)
          USING ERRCODE='check_violation';
      END IF;
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto
         SET quantidade = COALESCE(quantidade,0) - v_qtd,
             quantidade_reservada = LEAST(COALESCE(quantidade_reservada,0), COALESCE(quantidade,0) - v_qtd)
       WHERE id = p_item_id;
    ELSE
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto SET quantidade = COALESCE(quantidade,0) + v_qtd WHERE id = p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'devolucao' THEN
    v_classif := NULLIF(p_payload->>'classificacao','');
    IF v_classif IS NULL OR v_classif NOT IN ('reintegravel','quarentena','descarte','reprocesso') THEN
      RAISE EXCEPTION 'ESTQ_DEVOLUCAO_CLASSIFICACAO: informe reintegravel|quarentena|descarte|reprocesso.'
        USING ERRCODE='check_violation';
    END IF;
    IF v_motivo IS NULL THEN
      RAISE EXCEPTION 'ESTQ_MOTIVO_OBRIGATORIO: informe o motivo da devolução.' USING ERRCODE='check_violation';
    END IF;
    IF v_classif = 'reintegravel' THEN
      SELECT * INTO v_lote FROM public.lotes WHERE id = v_item.lote_id;
      IF NOT EXISTS (SELECT 1 FROM public.controle_qualidade cq
                      WHERE cq.lote_id = v_item.lote_id AND cq.resultado = 'aprovado'::resultado_cq) THEN
        RAISE EXCEPTION 'ESTQ_DEVOLUCAO_CQ: lote sem CQ aprovado não pode ser reintegrado ao estoque comercial.'
          USING ERRCODE='check_violation';
      END IF;
      IF v_item.validade IS NOT NULL AND v_item.validade < current_date THEN
        RAISE EXCEPTION 'ESTQ_DEVOLUCAO_VALIDADE: item vencido não pode ser reintegrado.' USING ERRCODE='check_violation';
      END IF;
      v_ctx := v_ctx || jsonb_build_object('metadata',
        COALESCE(v_ctx->'metadata','{}'::jsonb) || jsonb_build_object('classificacao', v_classif));
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto SET quantidade = COALESCE(quantidade,0) + v_qtd WHERE id = p_item_id;
    ELSE
      v_ctx := v_ctx || jsonb_build_object('metadata',
        COALESCE(v_ctx->'metadata','{}'::jsonb) || jsonb_build_object('classificacao', v_classif, 'reintegrado', false));
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      -- não reintegra saldo comercial: registra apenas a trilha da devolução
      UPDATE public.estoque_produto SET observacao_reserva = COALESCE(observacao_reserva, v_motivo) WHERE id = p_item_id;
      INSERT INTO public.estoque_movimentacoes
        (estoque_produto_id, acao, quantidade, status_anterior, status_novo, lote_id, usuario_id,
         saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
         unidade, direcao, origem, referencia_tipo, referencia_id, motivo,
         idempotency_key, request_fingerprint, metadata)
      VALUES (p_item_id, 'devolucao', v_qtd, v_item.status::text, v_item.status::text, v_item.lote_id, v_uid,
         COALESCE(v_item.quantidade,0), COALESCE(v_item.quantidade,0),
         COALESCE(v_item.quantidade_reservada,0), COALESCE(v_item.quantidade_reservada,0),
         COALESCE(p_payload->>'unidade','un'), 'neutro',
         COALESCE(p_payload->>'origem','rpc_estoque_operar_v1'),
         p_payload->>'referencia_tipo', NULLIF(p_payload->>'referencia_id','')::uuid, v_motivo,
         p_idempotency_key, v_fp,
         jsonb_build_object('classificacao', v_classif, 'reintegrado', false, 'motor','v1','stock_request_item',p_item_id::text,'stock_request_actor',v_uid::text));
    END IF;
    v_target_id := p_item_id;
  END IF;

  PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close();

  SELECT * INTO v_after FROM public.estoque_produto WHERE id = COALESCE(v_target_id, p_item_id);
  SELECT * INTO v_mov FROM public.estoque_movimentacoes
   WHERE idempotency_key = p_idempotency_key ORDER BY created_at DESC LIMIT 1;

  IF v_mov.id IS NULL THEN
    RAISE EXCEPTION 'ESTQ_SEM_TRILHA: operação não gerou lançamento no livro.' USING ERRCODE='internal_error';
  END IF;
  IF COALESCE(v_after.quantidade,0) < 0 OR COALESCE(v_after.quantidade_reservada,0) < 0 THEN
    RAISE EXCEPTION 'ESTQ_SALDO_NEGATIVO: operação resultaria em saldo negativo.' USING ERRCODE='check_violation';
  END IF;
  IF COALESCE(v_after.quantidade_reservada,0) > COALESCE(v_after.quantidade,0) THEN
    RAISE EXCEPTION 'ESTQ_RESERVA_MAIOR_QUE_SALDO' USING ERRCODE='check_violation';
  END IF;

  IF v_mov.usuario_id IS DISTINCT FROM v_uid OR v_mov.metadata->>'stock_request_item' IS DISTINCT FROM p_item_id::text OR NOT coalesce(public.stock_p1_movement_owned(v_mov.estoque_produto_id,v_mov.lote_id),false) THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object(
    'ok', true, 'replay', false, 'acao', p_acao,
    'movimentacao_id', v_mov.id, 'estoque_produto_id', COALESCE(v_target_id, p_item_id),
    'saldo_anterior', v_mov.saldo_anterior, 'saldo_posterior', v_mov.saldo_posterior,
    'reservado_anterior', v_mov.reservado_anterior, 'reservado_posterior', v_mov.reservado_posterior,
    'status_anterior', v_mov.status_anterior, 'status_novo', v_mov.status_novo,
    'quantidade', v_mov.quantidade, 'unidade', v_mov.unidade);
EXCEPTION WHEN OTHERS THEN PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close(); RAISE;
END; $function$;

public.rpc_estoque_reservar_v1.definition:
CREATE OR REPLACE FUNCTION public.rpc_estoque_reservar_v1(p_os_id uuid, p_origem text, p_itens jsonb, p_idempotency_key text, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid; v_actor uuid:=auth.uid(); v_tipo text; v_cliente uuid; v_partner uuid; v_order uuid; v_obs text;
 v_item jsonb; v_qty numeric; v_id uuid; v_payload jsonb; v_items jsonb; v_fp text; v_key text;
 v_prev platform_private.stock_batch_requests%ROWTYPE; v_result jsonb; v_call jsonb; v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
 v_org:=platform_private.stock_motor_actor('reserva');
 PERFORM platform_private.stock_motor_context_set(NULL);
 IF p_os_id IS NULL THEN RAISE EXCEPTION 'ESTQ_OS_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key))<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_origem IS NULL OR p_origem NOT IN ('padrao','manual','onfarm','on_farm','b2b') THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 v_tipo:=CASE WHEN p_origem='padrao' THEN 'manual' WHEN p_origem='on_farm' THEN 'onfarm' ELSE p_origem END;
 IF p_dados IS NULL OR jsonb_typeof(p_dados)<>'object' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_dados) e WHERE e.key NOT IN ('cliente_id','partner_id','partner_order_id','observacao') OR jsonb_typeof(e.value) NOT IN ('string','null')) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF p_itens IS NULL OR jsonb_typeof(p_itens)<>'array' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_itens)=0 THEN RAISE EXCEPTION 'ESTQ_ITENS_VAZIOS' USING ERRCODE='23514'; END IF;
 v_cliente:=nullif(p_dados->>'cliente_id','')::uuid; v_partner:=nullif(p_dados->>'partner_id','')::uuid; v_order:=nullif(p_dados->>'partner_order_id','')::uuid; v_obs:=nullif(p_dados->>'observacao','');
 v_payload:=jsonb_build_object('os_id',p_os_id,'os_tipo',v_tipo,'cliente_id',v_cliente,'partner_id',v_partner,'partner_order_id',v_order,'observacao',v_obs);
 v_items:='[]'::jsonb;
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
  IF jsonb_typeof(v_item)<>'object' OR NOT(v_item ? 'item_id' AND v_item ? 'quantidade') THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(v_item) e WHERE e.key NOT IN ('item_id','quantidade') OR (e.key='item_id' AND jsonb_typeof(e.value)<>'string') OR (e.key='quantidade' AND jsonb_typeof(e.value) NOT IN ('string','number'))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  IF v_qty IS NULL OR v_qty::text IN ('NaN','Infinity','-Infinity') OR v_qty<=0 THEN RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA' USING ERRCODE='23514'; END IF;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) e WHERE e->>'item_id'=v_id::text) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_items:=v_items||jsonb_build_array(jsonb_build_object('item_id',v_id,'quantidade',v_qty));
 END LOOP;
 SELECT jsonb_agg(value ORDER BY value->>'item_id') INTO v_items FROM jsonb_array_elements(v_items);
 v_fp:=md5(jsonb_build_object('actor',v_actor,'org',v_org,'os',p_os_id,'tipo',v_tipo,'payload',v_payload,'itens',v_items)::text);
 -- Global key collision is denied, never reused across actor/tenant/content. No wildcard comparisons.
 PERFORM pg_advisory_xact_lock(hashtextextended('stock_batch:'||p_idempotency_key,0));
 SELECT * INTO v_prev FROM platform_private.stock_batch_requests WHERE request_key=p_idempotency_key;
 IF FOUND THEN
  IF v_prev.actor IS DISTINCT FROM v_actor OR v_prev.organization_id IS DISTINCT FROM v_org OR v_prev.fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=p_idempotency_key OR left(idempotency_key,length(p_idempotency_key)+1)=p_idempotency_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
 -- Consistent item order before nested motor calls; all writes are one transaction.
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid;
  PERFORM 1 FROM public.estoque_produto WHERE id=v_id FOR UPDATE;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
 END LOOP;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  v_key:='stock_batch_item:'||md5(jsonb_build_array(p_idempotency_key,v_actor,v_org,v_id)::text);
  IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=v_key OR left(idempotency_key,length(v_key)+1)=v_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  v_call:=public.rpc_estoque_operar_v1('reserva',v_id,v_qty,v_key,v_payload);
  IF v_call->>'ok' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  -- The ledger is canonical for the split target, not the source item.
  SELECT estoque_produto_id INTO v_id FROM public.estoque_movimentacoes WHERE id=(v_call->>'movimentacao_id')::uuid;
  IF v_id IS NULL THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  v_ids:=array_append(v_ids,v_id);
 END LOOP;
 v_result:=jsonb_build_object('ok',true,'replay',false,'itens',to_jsonb(v_ids));
 INSERT INTO platform_private.stock_batch_requests(request_key,actor,organization_id,fingerprint,result) VALUES(p_idempotency_key,v_actor,v_org,v_fp,v_result);
 PERFORM platform_private.stock_motor_context_set(NULL);
 RETURN v_result;
END $function$;

platform_private.stock_p1_guard.definition:
CREATE OR REPLACE FUNCTION platform_private.stock_p1_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid := public.h15_actor_organization();
 v_ref uuid;
 v_lote public.lotes%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND NOT platform_private.stock_p1_lote_owned(OLD.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 IF NOT platform_private.stock_p1_lote_owned(NEW.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_lote FROM public.lotes WHERE id=NEW.lote_id;
 -- Explicit lote ownership is required; parent references never assign ownership.
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.programacao_producao p
   WHERE p.id=v_lote.programacao_id AND p.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.envase_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.envase e WHERE e.id=NEW.envase_id
   AND e.lote_id=NEW.lote_id AND e.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_cliente_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.clientes c WHERE c.id=NEW.reservado_para_cliente_id AND c.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_partner_id IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(NEW.reservado_para_partner_id,false),false) THEN
  RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF NEW.reservado_para_partner_order_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.reservado_para_partner_order_id
    AND o.partner_id=NEW.reservado_para_partner_id
    AND public.b2b_phase1_order_visible(o.id)
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_os_id IS NOT NULL THEN
  IF NEW.reservado_para_os_tipo IN ('onfarm','on_farm') THEN
   SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o
    JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.reservado_para_os_id;
  ELSIF NEW.reservado_para_os_tipo IN ('manual','b2b') THEN
   SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.reservado_para_os_id;
  ELSE
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF v_ref IS DISTINCT FROM v_org THEN
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END;
$function$;

platform_private.stock_p1_movement_guard.definition:
CREATE OR REPLACE FUNCTION platform_private.stock_p1_movement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_org uuid:=public.h15_actor_organization(); v_lote uuid; v_ref uuid;
BEGIN
IF auth.uid() IS NULL OR v_org IS NULL THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
SELECT e.lote_id INTO v_lote FROM public.estoque_produto e WHERE e.id=NEW.estoque_produto_id;
IF v_lote IS NULL OR NOT platform_private.stock_p1_lote_owned(v_lote) THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
-- Only a new ledger row may inherit its verified stock's lote, never organization or legacy backfill.
IF NEW.lote_id IS NULL THEN NEW.lote_id:=v_lote; END IF;
IF NEW.lote_id IS DISTINCT FROM v_lote THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.cliente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=NEW.cliente_id AND c.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.os_id IS NOT NULL THEN
 IF NEW.os_tipo IN ('manual','b2b') THEN SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.os_id;
 ELSIF NEW.os_tipo IN ('onfarm','on_farm') THEN SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.os_id;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_ref IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
END IF;
IF NEW.movimentacao_origem_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes m WHERE m.id=NEW.movimentacao_origem_id AND m.estoque_produto_id=NEW.estoque_produto_id AND m.lote_id=NEW.lote_id) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.referencia_id IS NOT NULL THEN
 IF NEW.referencia_tipo='entrega' THEN
  IF NOT EXISTS(SELECT 1 FROM public.entregas e WHERE e.id=NEW.referencia_id AND e.organization_id=v_org AND (e.lote_id IS NULL OR e.lote_id=NEW.lote_id) AND (NEW.cliente_id IS NULL OR e.cliente_id=NEW.cliente_id)) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('estoque','estoque_produto') THEN
  IF NEW.referencia_id IS DISTINCT FROM NEW.estoque_produto_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('os','ordem_servico') THEN
  IF NEW.os_id IS NULL OR NEW.referencia_id IS DISTINCT FROM NEW.os_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
END IF;
RETURN NEW;
END $function$;

public.log_estoque_movimentacao.definition:
CREATE OR REPLACE FUNCTION public.log_estoque_movimentacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb := public.fn_estoque_ctx_read();
  v_acao text;
  v_dir text;
  v_usuario uuid;
  v_old_status text;
  v_new_status text;
  v_qtd numeric;
  v_mudou boolean;
  v_key text := v_ctx->>'idempotency_key';
  v_meta jsonb := COALESCE(v_ctx->'metadata', '{}'::jsonb);
  v_seq int;
BEGIN
  -- Uma operação do motor pode tocar mais de uma linha (reserva parcial).
  -- O lançamento principal fica com a chave da operação; os complementares
  -- recebem chave derivada determinística e são marcados como desdobramento.
  IF v_key IS NOT NULL THEN
    SELECT count(*) INTO v_seq
      FROM public.estoque_movimentacoes
     WHERE idempotency_key = v_key OR left(idempotency_key,length(v_key)+1) = v_key || '#';
    IF v_seq > 0 THEN
      v_meta := v_meta || jsonb_build_object('desdobramento', true, 'operacao_key', v_key);
      v_key := v_key || '#' || v_seq::text;
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.estoque_movimentacoes
      (estoque_produto_id, acao, quantidade, status_novo, lote_id, usuario_id,
       saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
       volume_anterior, volume_posterior, unidade, direcao,
       origem, referencia_tipo, referencia_id, motivo, idempotency_key, request_fingerprint,
       movimentacao_origem_id, os_id, os_tipo, cliente_id, metadata)
    VALUES (
      NEW.id,
      COALESCE(v_ctx->>'acao', 'entrada'),
      NULLIF(NEW.quantidade, 0), NEW.status::text, NEW.lote_id,
      COALESCE(auth.uid(), (v_ctx->>'usuario_id')::uuid),
      0, COALESCE(NEW.quantidade, 0),
      0, COALESCE(NEW.quantidade_reservada, 0),
      0, COALESCE(NEW.volume_total, 0),
      COALESCE(v_ctx->>'unidade', 'un'), 'entrada',
      COALESCE(v_ctx->>'origem', 'trigger'),
      v_ctx->>'referencia_tipo', (v_ctx->>'referencia_id')::uuid,
      v_ctx->>'motivo', v_key, v_ctx->>'request_fingerprint',
      (v_ctx->>'movimentacao_origem_id')::uuid,
      NEW.reservado_para_os_id, NEW.reservado_para_os_tipo, NEW.reservado_para_cliente_id,
      v_meta
    );
    RETURN NEW;
  END IF;

  v_mudou := (OLD.status IS DISTINCT FROM NEW.status)
          OR (COALESCE(OLD.quantidade,0) IS DISTINCT FROM COALESCE(NEW.quantidade,0))
          OR (COALESCE(OLD.quantidade_reservada,0) IS DISTINCT FROM COALESCE(NEW.quantidade_reservada,0))
          OR (COALESCE(OLD.volume_total,0) IS DISTINCT FROM COALESCE(NEW.volume_total,0));
  IF NOT v_mudou THEN RETURN NEW; END IF;

  v_old_status := OLD.status::text;
  v_new_status := NEW.status::text;

  v_acao := COALESCE(v_ctx->>'acao', CASE
    WHEN v_new_status = 'reservado'  AND v_old_status = 'expedido'  THEN 'estorno_expedicao'
    WHEN v_new_status = 'reservado'  AND v_old_status <> 'reservado' THEN 'reserva'
    WHEN v_new_status = 'expedido'   AND v_old_status <> 'expedido'  THEN 'expedicao'
    WHEN v_new_status = 'estornado'                                  THEN 'estorno_expedicao'
    WHEN v_old_status = 'reservado'  AND v_new_status = 'disponivel' THEN 'cancelamento_reserva'
    WHEN v_old_status = v_new_status THEN 'ajuste'
    ELSE 'edicao'
  END);

  v_dir := COALESCE(v_ctx->>'direcao', CASE
    WHEN COALESCE(NEW.quantidade,0) > COALESCE(OLD.quantidade,0) THEN 'entrada'
    WHEN COALESCE(NEW.quantidade,0) < COALESCE(OLD.quantidade,0) THEN 'saida'
    WHEN v_acao IN ('expedicao','descarte','perda','consumo','entrega') THEN 'saida'
    WHEN v_acao IN ('estorno_expedicao','devolucao') THEN 'entrada'
    ELSE 'neutro'
  END);

  v_usuario := COALESCE(auth.uid(), (v_ctx->>'usuario_id')::uuid,
    CASE WHEN v_new_status = 'expedido' THEN NEW.expedido_por ELSE NEW.reservado_por END);

  v_qtd := NULLIF(ABS(COALESCE(NEW.quantidade,0) - COALESCE(OLD.quantidade,0)), 0);
  IF v_qtd IS NULL THEN
    v_qtd := NULLIF(ABS(COALESCE(NEW.quantidade_reservada,0) - COALESCE(OLD.quantidade_reservada,0)), 0);
  END IF;
  IF v_qtd IS NULL THEN
    v_qtd := NULLIF(COALESCE(NEW.quantidade_reservada, NEW.quantidade, 0), 0);
  END IF;

  INSERT INTO public.estoque_movimentacoes
    (estoque_produto_id, acao, quantidade, status_anterior, status_novo,
     os_id, os_tipo, cliente_id, lote_id, usuario_id, observacao,
     saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
     volume_anterior, volume_posterior, unidade, direcao,
     origem, referencia_tipo, referencia_id, motivo,
     idempotency_key, request_fingerprint, movimentacao_origem_id, metadata)
  VALUES (
    NEW.id, v_acao, v_qtd, v_old_status, v_new_status,
    NEW.reservado_para_os_id, NEW.reservado_para_os_tipo, NEW.reservado_para_cliente_id,
    NEW.lote_id, v_usuario, COALESCE(v_ctx->>'observacao', NEW.observacao_reserva),
    COALESCE(OLD.quantidade,0), COALESCE(NEW.quantidade,0),
    COALESCE(OLD.quantidade_reservada,0), COALESCE(NEW.quantidade_reservada,0),
    COALESCE(OLD.volume_total,0), COALESCE(NEW.volume_total,0),
    COALESCE(v_ctx->>'unidade','un'), v_dir,
    COALESCE(v_ctx->>'origem','trigger'),
    v_ctx->>'referencia_tipo', (v_ctx->>'referencia_id')::uuid, v_ctx->>'motivo',
    v_key, v_ctx->>'request_fingerprint',
    (v_ctx->>'movimentacao_origem_id')::uuid,
    v_meta
  );

  IF v_acao = 'reserva' THEN
    INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
    SELECT ur.user_id, 'nova_reserva', 'Nova reserva de estoque',
           'Item reservado aguardando expedição.', '/estoque'
      FROM public.user_roles ur JOIN public.profiles pr ON pr.user_id=ur.user_id AND pr.ativo IS TRUE JOIN public.lotes l ON l.id=NEW.lote_id AND l.organization_id=pr.organization_id JOIN public.organizations o ON o.id=pr.organization_id AND o.ativo IS TRUE WHERE ur.role = 'administrativo'::app_role AND l.organization_id IS NOT NULL;
  END IF;

  RETURN NEW;
END;
$function$;

platform_private.stock_motor_actor.definition:
CREATE OR REPLACE FUNCTION platform_private.stock_motor_actor(p_acao text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_org uuid; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'ESTQ_NAO_AUTENTICADO' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL THEN RAISE EXCEPTION 'ESTQ_IDENTIDADE_INATIVA' USING ERRCODE='42501'; END IF;
 IF NOT coalesce(public.fn_estoque_pode_operar(auth.uid(),p_acao),false) THEN RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO' USING ERRCODE='42501'; END IF;
 IF NOT coalesce(public.saas_has_feature('estoque_embalagens'),false) THEN RAISE EXCEPTION 'ESTQ_FEATURE_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN v_org;
END $function$;

platform_private.stock_motor_context_set.definition:
CREATE OR REPLACE FUNCTION platform_private.stock_motor_context_set(p_ctx jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 DELETE FROM platform_private.stock_motor_context WHERE txid=txid_current();
 IF p_ctx IS NOT NULL THEN
  PERFORM platform_private.stock_motor_actor(p_ctx->>'acao');
  IF p_ctx->>'usuario_id' IS DISTINCT FROM auth.uid()::text OR jsonb_typeof(p_ctx->'metadata') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  INSERT INTO platform_private.stock_motor_context(txid,actor,item,ctx) VALUES(txid_current(),auth.uid(),(p_ctx->'metadata'->>'stock_request_item')::uuid,p_ctx);
 END IF;
 PERFORM public.fn_estoque_ctx_force(p_ctx);
END $function$;

platform_private.stock_motor_item.definition:
CREATE OR REPLACE FUNCTION platform_private.stock_motor_item(p_item uuid, p_acao text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_org uuid; v_item public.estoque_produto%ROWTYPE; v_lote public.lotes%ROWTYPE;
BEGIN
 v_org:=platform_private.stock_motor_actor(p_acao);
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR (p_payload ? 'metadata' AND jsonb_typeof(p_payload->'metadata')<>'object') OR p_payload ?| ARRAY['organization_id','tenant_id','usuario_id','user_id','owner_id'] OR coalesce(p_payload->'metadata','{}'::jsonb) ?| ARRAY['stock_request_item','stock_request_actor','stock_request_fp'] THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_payload) e WHERE e.key IN ('motivo','observacao','origem','referencia_tipo','referencia_id','os_id','os_tipo','cliente_id','partner_id','partner_order_id','movimentacao_origem_id','classificacao','sentido','unidade') AND jsonb_typeof(e.value) NOT IN ('string','null')) OR (p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida')) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 -- Scoped lookup never returns a foreign/orphan row, even under DEFINER.
 SELECT e.* INTO v_item FROM public.estoque_produto e JOIN public.lotes l ON l.id=e.lote_id WHERE e.id=p_item AND l.organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT l.* INTO v_lote FROM public.lotes l WHERE l.id=v_item.lote_id AND l.organization_id=v_org;
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.programacao_producao g WHERE g.id=v_lote.programacao_id AND g.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_item.envase_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.envase e WHERE e.id=v_item.envase_id AND e.lote_id=v_item.lote_id AND e.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.stock_motor_refs(p_item,v_item.lote_id,v_org,jsonb_build_object('os_id',v_item.reservado_para_os_id,'os_tipo',v_item.reservado_para_os_tipo,'cliente_id',v_item.reservado_para_cliente_id,'partner_id',v_item.reservado_para_partner_id,'partner_order_id',v_item.reservado_para_partner_order_id));
 PERFORM platform_private.stock_motor_refs(p_item,v_item.lote_id,v_org,p_payload);
END $function$;

platform_private.stock_motor_refs.definition:
CREATE OR REPLACE FUNCTION platform_private.stock_motor_refs(p_item uuid, p_lote uuid, p_org uuid, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_os uuid:=nullif(p->>'os_id','')::uuid; v_tipo text:=p->>'os_tipo'; v_cliente uuid:=nullif(p->>'cliente_id','')::uuid;
 v_partner uuid:=nullif(p->>'partner_id','')::uuid; v_order uuid:=nullif(p->>'partner_order_id','')::uuid;
 v_ref uuid:=nullif(p->>'referencia_id','')::uuid; v_rt text:=p->>'referencia_tipo'; v_origin uuid:=nullif(p->>'movimentacao_origem_id','')::uuid;
 v_os_cliente uuid; v_os_order uuid;
BEGIN
 IF v_cliente IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=v_cliente AND c.organization_id=p_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_partner IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(v_partner,false),false) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_order IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.partner_orders o WHERE o.id=v_order AND o.partner_id=v_partner AND public.b2b_phase1_order_visible(o.id)) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_os IS NOT NULL THEN
  IF v_tipo IN ('manual','b2b') THEN
   SELECT o.cliente_id,o.partner_order_id INTO v_os_cliente,v_os_order FROM public.ordens_servico o WHERE o.id=v_os AND o.organization_id=p_org;
   IF NOT FOUND THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
   IF v_tipo='b2b' AND (v_order IS NULL OR v_os_order IS DISTINCT FROM v_order OR v_cliente IS NOT NULL) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
   IF v_tipo='manual' AND (v_os_order IS NOT NULL OR v_partner IS NOT NULL OR v_order IS NOT NULL) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  ELSIF v_tipo IN ('onfarm','on_farm') THEN
   SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=v_os AND c.organization_id=p_org;
   IF NOT FOUND OR v_partner IS NOT NULL OR v_order IS NOT NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  ELSE RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
  IF v_cliente IS NOT NULL AND v_cliente IS DISTINCT FROM v_os_cliente THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 END IF;
 IF v_origin IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes m WHERE m.id=v_origin AND m.estoque_produto_id=p_item AND m.lote_id=p_lote AND public.stock_p1_movement_owned(m.estoque_produto_id,m.lote_id)) THEN RAISE EXCEPTION 'ESTQ_ESTORNO_ORIGEM_INVALIDA' USING ERRCODE='42501'; END IF;
 -- Only proven existing guard semantics. Unsupported literals fail even without an ID.
 IF v_rt IS NOT NULL AND v_rt NOT IN ('entrega','ordem_servico','manual','sistema') THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_rt IN ('manual','sistema') AND v_ref IS NOT NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_ref IS NOT NULL AND v_rt IS NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_rt IN ('entrega','ordem_servico') AND v_ref IS NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_rt='ordem_servico' AND (v_os IS NULL OR v_ref IS DISTINCT FROM v_os OR v_tipo NOT IN ('manual','b2b','onfarm','on_farm')) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_rt='entrega' AND NOT EXISTS(SELECT 1 FROM public.entregas e WHERE e.id=v_ref AND e.organization_id=p_org AND e.estoque_produto_id=p_item AND (e.lote_id IS NULL OR e.lote_id=p_lote) AND (v_cliente IS NULL OR e.cliente_id=v_cliente) AND (v_os IS NULL OR (v_tipo IN ('manual','b2b') AND e.ordem_servico_id=v_os) OR (v_tipo IN ('onfarm','on_farm') AND e.ordem_servico_onfarm_id=v_os))) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
END $function$;

public._comunicacao_trg_os_pronto_retira.definition:
CREATE OR REPLACE FUNCTION public._comunicacao_trg_os_pronto_retirada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_idem text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'pronto_entrega'::public.status_os THEN
    v_idem := 'os_pronto_retirada:ordens_servico:' || NEW.id::text;
    PERFORM public._comunicacao_publish_system_event(
      'produto_pronto_retirada','ordens_servico', NEW.id, '{}'::jsonb, v_idem);
  END IF;
  RETURN NEW;
END$function$;

