$function$;

public.validate_estoque_reserva.definition:
CREATE OR REPLACE FUNCTION public.validate_estoque_reserva()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status::text = 'reservado' AND (OLD.status IS DISTINCT FROM NEW.status OR OLD.status::text <> 'reservado') THEN
    IF NEW.reservado_para_os_id IS NULL THEN
      RAISE EXCEPTION 'Reserva requer uma OS vinculada.' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.reservado_para_os_tipo = 'b2b' THEN
      IF NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva B2B requer um parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.reservado_para_cliente_id IS NULL AND NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva requer um cliente ou parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    IF NEW.quantidade_reservada IS NULL OR NEW.quantidade_reservada <= 0 THEN
      RAISE EXCEPTION 'Informe uma quantidade reservada maior que zero.' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.quantidade IS NOT NULL AND NEW.quantidade_reservada > NEW.quantidade THEN
      RAISE EXCEPTION 'Quantidade reservada (%) excede o estoque disponível (%).', NEW.quantidade_reservada, NEW.quantidade
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reservado_em IS NULL THEN NEW.reservado_em := now(); END IF;
    IF NEW.reservado_por IS NULL THEN NEW.reservado_por := auth.uid(); END IF;
  END IF;

  IF NEW.status::text = 'disponivel' AND OLD.status::text = 'reservado' THEN
    NEW.reservado_para_os_id := NULL;
    NEW.reservado_para_os_tipo := NULL;
    NEW.reservado_para_cliente_id := NULL;
    NEW.reservado_para_partner_id := NULL;
    NEW.reservado_para_partner_order_id := NULL;
    NEW.quantidade_reservada := NULL;
    NEW.reservado_por := NULL;
    NEW.reservado_em := NULL;
    NEW.observacao_reserva := NULL;
  END IF;

  IF NEW.status::text = 'expedido' AND OLD.status::text <> 'expedido' THEN
    IF NEW.expedido_em IS NULL THEN NEW.expedido_em := now(); END IF;
    IF NEW.expedido_por IS NULL THEN NEW.expedido_por := auth.uid(); END IF;
  END IF;

  RETURN NEW;
END;
$function$;

public.validate_estoque_entrada.definition:
CREATE OR REPLACE FUNCTION public.validate_estoque_entrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Reservas parciais (têm quantidade_reservada preenchida) seguem normalmente
  IF NEW.quantidade_reservada IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Exigir envase para o lote
  IF NOT EXISTS (SELECT 1 FROM public.envase WHERE lote_id = NEW.lote_id) THEN
    RAISE EXCEPTION 'Não é possível criar entrada no estoque: o lote ainda não possui registro de envase.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Bloquear duplicidade por envase_id (não mais por lote)
  IF NEW.envase_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE envase_id = NEW.envase_id
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe entrada de estoque para este envase.'
      USING ERRCODE = 'unique_violation';
  END IF;

  -- Compat: se a entrada vier sem envase_id, manter a regra antiga de 1 por lote
  IF NEW.envase_id IS NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE lote_id = NEW.lote_id
      AND envase_id IS NULL
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe uma entrada de estoque agregada para este lote.'
      USING ERRCODE = 'unique_violation';
  END IF;

  RETURN NEW;
END;
$function$;

public.validate_responsavel_producao.definition:
CREATE OR REPLACE FUNCTION public.validate_responsavel_producao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_ok boolean;
BEGIN
  IF NEW.responsavel_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_user_id
  FROM public.profiles
  WHERE id = NEW.responsavel_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Responsável inválido: perfil não encontrado'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_user_id
      AND role::text IN ('administrador','gestor','operador_onfarm','producao')
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Responsável inválido: perfil sem permissão para produção do laboratório'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$;

